import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { render } from "@testing-library/react";
import { createElement } from "react";
import { describe, expect, it } from "vitest";
import { Button } from "../src/components/ui/button";
// Generated by scripts/prepare-parity.ts from the built registry item before Vitest starts.
import { Button as CopyButton } from "../test-fixture/components/ui/button";

describe("registry copy parity", () => {
  it("renders the same markup as the package for the same props", () => {
    const props = { variant: "outline" as const, size: "lg" as const, children: "Parity" };

    const packageRender = render(createElement(Button, props));
    const packageHtml = packageRender.container.innerHTML;
    packageRender.unmount();

    const copyRender = render(createElement(CopyButton, props));
    expect(copyRender.container.innerHTML).toBe(packageHtml);
  });

  it("records the source version in the installed sidecar", () => {
    const item = JSON.parse(
      readFileSync(resolve(import.meta.dirname, "../../../apps/docs/public/r/button.json"), "utf8"),
    ) as { files: Array<{ type: string; content?: string }> };
    const sidecar = item.files.find((file) => file.type === "registry:file");
    expect(sidecar?.content).toContain('"version": "0.1.0"');
  });
});
